public sealed class Order
{
    private readonly List<OrderItem> _items = new();

    public int Id { get; private set; }
    public string CustomerName { get; private set; } = "";
    public decimal Total { get; private set; }
    public uint RowVersion { get; private set; }          // Postgres xmin
    public IReadOnlyCollection<OrderItem> Items => _items.AsReadOnly();

    private Order() { }                                    // EF materialization

    public Order(string customerName)
    {
        if (string.IsNullOrWhiteSpace(customerName))
            throw new ArgumentException("customer name required", nameof(customerName));
        CustomerName = customerName;
    }

    public void AddItem(OrderItem item)
    {
        _items.Add(item);
        Total += item.Price * item.Quantity;
    }
}

public sealed class OrderConfiguration : IEntityTypeConfiguration<Order>
{
    public void Configure(EntityTypeBuilder<Order> builder)
    {
        builder.ToTable("orders");
        builder.HasKey(o => o.Id);
        builder.Property(o => o.CustomerName).IsRequired().HasMaxLength(200);
        builder.Property(o => o.Total).HasPrecision(18, 2).HasDefaultValueSql("0");
        builder.Property(o => o.RowVersion).IsRowVersion();
        builder.HasIndex(o => o.CustomerName);

        // SetNull rather than Cascade: two cascade paths onto one table is
        // what SqlServer rejects at migration-apply time.
        builder.HasMany(o => o.Items)
            .WithOne(i => i.Order)
            .HasForeignKey(i => i.OrderId)
            .OnDelete(DeleteBehavior.SetNull);
    }
}

// AppDbContext.OnModelCreating — this call and nothing else:
//   modelBuilder.ApplyConfigurationsFromAssembly(typeof(AppDbContext).Assembly);

public sealed record OrderDto(int Id, string CustomerName, decimal Total);
public sealed record PagedResult<T>(
    IReadOnlyList<T> Items, int TotalCount, int Page, int PageSize);

public async Task<PagedResult<OrderDto>> ListAsync(
    int page, int pageSize, CancellationToken ct)
{
    var query = _db.Orders
        .AsNoTracking()
        .Include(o => o.Items)
        .Include(o => o.Discounts)
        // Two collection navigations: without this the JOIN returns
        // orders x items x discounts rows for a single page.
        .AsSplitQuery()
        .OrderBy(o => o.Id);

    var total = await query.CountAsync(ct);
    var items = await query
        .Skip((page - 1) * pageSize)
        .Take(pageSize)
        .Select(o => new OrderDto(o.Id, o.CustomerName, o.Total))
        .ToListAsync(ct);

    return new PagedResult<OrderDto>(items, total, page, pageSize);
}

// One SQL statement, no change tracker, no per-row round trip.
await _db.Orders
    .Where(o => o.Status == OrderStatus.Draft && o.CreatedAt < cutoff)
    .ExecuteDeleteAsync(ct);

await _db.Orders
    .Where(o => o.CustomerId == customerId)
    .ExecuteUpdateAsync(s => s.SetProperty(o => o.Region, region), ct);

